(function() {
    'use strict';

    class HospitalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Healthcare System Navigator';
            this.version = '2.2.0';

            // ---- Operating model constants -------------------------------------------------
            // v2.1.0 CALIBRATION NOTE. In v2.0.0 the cost ratios summed to 0.98 of revenue
            // BEFORE the turnover penalty, agency premium, quality spend, overtime and the
            // strategic initiative were added — so the hospital was structurally incapable of
            // turning a profit. Measured margin on default decisions: -13.6%, best case -9.6%.
            // Because financialScore uses max(0, margin * 2000), that term was PERMANENTLY ZERO.
            // The ratios below are re-anchored so that DEFAULT decisions in Q1 reproduce the
            // 3.2% operating margin the sim's own briefing promises. "Fixed" cost is now an
            // actual fixed dollar amount rather than a percentage of revenue (a contradiction in
            // terms, and the reason volume produced no operating leverage).
            this.LABOR_BASE   = 0.58;      // share of revenue, before turnover/ratio adjustments
            this.SUPPLY_RATIO = 0.16;
            this.ADMIN_RATIO  = 0.07;
            this.FIXED_COST   = 765000;    // per quarter, ABSOLUTE (was 0.12 x revenue)
            this.BASE_RATE    = 4500;      // revenue per discharge
            this.EMERGENCY_DISCHARGES = 8500 / 6;   // baseline medical/ED throughput per quarter
            this.WEEKS_PER_QUARTER    = 13;
            this.TARGET_ICU_PCT       = 15;         // case-mix appropriate ICU share

            // Shock pools. v2.0.0 selected with `SHOCK_SCENARIOS.find(s => s.quarter === q)`,
            // which returns the FIRST match — so Q3 was always 'dengue', Q4 always 'audit',
            // and 5 of the 8 authored scenarios (strike, inspection, ehr_failure, competitor,
            // exodus) could never fire in any playthrough. Every run was identical.
            this.SHOCK_SCENARIOS = [
                { id: 'dengue',       quarter: 3, impact: { edVolume: 1.4 } },
                { id: 'strike',       quarter: 3, impact: { nurseAvailability: 0.7, costPremium: 1.4 } },
                { id: 'inspection',   quarter: 3, impact: { complianceCost: 80000, reputationHit: 15 } },
                { id: 'ehr_failure',  quarter: 3, impact: { errorRate: 2.5 } },
                { id: 'audit',        quarter: 4, impact: { cashPenalty: 150000, receivablesDelay: 30 } },
                { id: 'competitor',   quarter: 4, impact: { privateVolumeLoss: 0.15 } },
                { id: 'exodus',       quarter: 4, impact: { physicianCapacity: 0.75 } },
                { id: 'pandemic_prep',quarter: 5, impact: { capacityReduction: 0.1 } }
            ];

            this.STRATEGIC_COSTS = {
                ehr: 150000, lean: 80000, accreditation: 120000,
                service: 200000, community: 60000, partnership: 100000
            };

            // v2.1.0 — Strategic initiative effects.
            // In v2.0.0 only 'lean' (efficiency) and 'community' (+400 community score) did
            // anything at all. 'ehr', 'accreditation', 'service' and 'partnership' deducted
            // $150K/$120K/$200K/$100K per quarter and changed NOTHING else — four of six options
            // in Panel E were strictly dominated money-burners.
            //
            // >>> THE COEFFICIENTS BELOW ARE NEWLY AUTHORED GAME DESIGN, NOT A RESTORED
            // >>> SPECIFICATION. They are plausible and internally consistent, but they are my
            // >>> proposal and need product sign-off. See the review note.
            this.INITIATIVE_EFFECTS = {
                ehr:           { adminRatioDelta: -0.010, medSafetyBoost: 0.25, errorShockShield: 0.5 },
                lean:          { /* handled via leanEngagement, unchanged from v2.0.0 */ },
                accreditation: { qualityBonus: 60, revenueMult: 1.02 },
                service:       { revenueMult: 1.06, requiresIcuPct: 18, penaltyIfUnsupported: 0.03 },
                community:     { communityBonus: 400 },
                partnership:   { volumeMult: 1.04, communityBonus: 150 }
            };
        }

        // ---------- i18n ----------

        _t(key) {
            try {
                var s = window.mySimulation.t(key);
                return (s === undefined || s === null) ? key : s;
            } catch (e) { return key; }
        }
        _tv(key, vars) {
            var s = this._t(key);
            if (vars) Object.keys(vars).forEach(function(k) { s = s.split('{' + k + '}').join(vars[k]); });
            return s;
        }

        // ---------- lifecycle ----------

        _freshDomainState() {
            return {
                cash: 8500000,
                totalBeds: 300,
                icuBeds: 45,
                baseNurseTurnover: 0.22,
                currentNurseTurnover: 0.22,
                nurseSatisfaction: 65,
                baseHaiRate: 0.021,
                currentHaiRate: 0.021,
                baseReadmissionRate: 0.124,
                currentReadmissionRate: 0.124,
                baseEdWait: 45,
                currentEdWait: 45,
                baseNps: 32,
                currentNps: 32,
                occupancy: 0.78,
                operatingMargin: 0.032,
                daysCashOnHand: 42,
                totalRevenue: 0,
                totalCosts: 0,
                qualityScore: 650,
                efficiencyScore: 650,
                financialScore: 650,
                workforceScore: 650,
                communityScore: 650,
                cumulativeScore: 0,
                qualityHistory: [], financialHistory: [], efficiencyHistory: [],
                workforceHistory: [], communityHistory: [], scoreHistory: [],
                strategicInvestments: [], activeInitiatives: [],
                leanEngagement: 0,
                shockHistory: [],
                shocks: null          // { '3': id, '4': id, '5': id } — drawn once, deterministic
            };
        }

        _freshDecisions() {
            return {
                bedAllocation: 15, edThreshold: 85, electiveSlots: 40, nurseRatio: 5,
                overtimeBudget: 25000, trainingInvestment: 10000, infectionControl: 15000,
                medicationSafety: 20000, readmissionProgram: 10000, contractStance: 'accept',
                revenueCycle: 10000, charityCare: 20000, strategicInitiative: 'lean'
            };
        }

        initialize(state) {
            // BUGFIX v2.1.0: undoLastPeriod() falls back to initialize() once history is empty,
            // but the `domainState is empty` guard never fires because it still holds Q1 results.
            // Undo of Q1 left a stale scoreHistory and the replay appended a duplicate.
            // (Same defect found in sims 004 and 005 — this is a portfolio-wide pattern.)
            var noHistory = !state.history || state.history.length === 0;

            if (!state.domainState || Object.keys(state.domainState).length === 0 || noHistory) {
                state.domainState = this._freshDomainState();
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0 || noHistory) {
                state.decisions = this._freshDecisions();
            }
            if (!state.domainState.shocks) {
                state.domainState.shocks = this._drawShocks(this._sessionSeed());
            }
            this._updateBriefing(state);
        }

        // Deterministic, seeded draw — one scenario per shock quarter, from that quarter's pool.
        // All 8 scenarios are now reachable. A session-level seed (same cohort -> same shocks)
        // belongs in the framework/DB and is not available here; we derive a stable seed and
        // fall back to a constant.
        _sessionSeed() {
            try {
                var st = window.mySimulation && window.mySimulation.state;
                if (st && st.metadata && st.metadata.sessionSeed) return st.metadata.sessionSeed | 0;
            } catch (e) { /* fall through */ }
            return 0x5EED;
        }

        _drawShocks(seed) {
            var self = this;
            var out = {};
            [3, 4, 5].forEach(function(q) {
                var pool = self.SHOCK_SCENARIOS.filter(function(s) { return s.quarter === q; });
                if (!pool.length) return;
                var s = (seed ^ (q * 2654435761)) | 0;
                s ^= s << 13; s = s | 0;
                s ^= s >>> 17;
                s ^= s << 5;  s = s | 0;
                out[q] = pool[Math.abs(s) % pool.length].id;
            });
            return out;
        }

        _shockFor(period, ds) {
            if (!ds || !ds.shocks) return null;
            var id = ds.shocks[period] || ds.shocks[String(period)];
            if (!id) return null;
            return this.SHOCK_SCENARIOS.filter(function(s) { return s.id === id; })[0] || null;
        }

        _showCompletion() {
            var panel = document.getElementById('completionPanel');
            if (!panel) return;
            var sim = window.mySimulation;
            var html = sim && sim.lastCompletionHTML;
            if (!html && sim && sim.lastSummary && this.formatCompletionMessage) {
                html = this.formatCompletionMessage(sim.lastSummary);
            }
            if (!html) return;
            panel.innerHTML = html;
            panel.style.display = 'block';
            if (typeof panel.focus === 'function') { try { panel.focus(); } catch (e) {} }
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var self = this;
            var raw = summary.insightKeys || summary.insights || [];
            var items = raw.map(function(k) {
                // accept either i18n keys or already-rendered strings
                var txt = self._t(k);
                return '<li>' + (txt === k && String(k).indexOf(' ') !== -1 ? k : txt) + '</li>';
            }).join('');
            var pct = function(v) { return (typeof v === 'string') ? v : ((Math.round((v || 0) * 10) / 10) + '%'); };
            return ''
                + '<h3>' + this._t('completion_title') + '</h3>'
                + '<div><span class="hospital-sim-score">' + (summary.overallScore || 0) + '<span style="font-size:1rem">/100</span></span>'
                + '<span class="hospital-sim-band">' + (summary.band || '') + '</span></div>'
                + '<div class="hospital-sim-kpirow">'
                + this._t('kpi_cumulative') + ': <b>' + Math.round(summary.totalScore || 0) + '</b> &middot; '
                + this._t('kpi_margin') + ': <b>' + pct(summary.finalMargin) + '</b> &middot; '
                + this._t('kpi_turnover') + ': <b>' + pct(summary.finalTurnover) + '</b> &middot; '
                + this._t('kpi_hai') + ': <b>' + (Math.round((summary.finalHai || 0) * 100) / 100) + '</b>'
                + '</div>'
                + (items ? '<p><b>' + this._t('completion_insights') + '</b></p><ul>' + items + '</ul>' : '')
                + '<p>' + this._t('completion_thanks') + '</p>';
        }

        _updateBriefing(state) {
            if (!state || !state.domainState) return;

            var q  = state.currentPeriod || 1;
            var ds = state.domainState;
            if (!ds.shockHistory) ds.shockHistory = [];

            var briefEl    = document.getElementById('briefingText');
            var alertPanel = document.getElementById('alertPanel');
            var alertText  = document.getElementById('alertText');
            if (!briefEl) return;

            var finished = q > 6;
            briefEl.innerHTML = finished ? this._t('end_body') : this._t('brief' + Math.min(q, 6));

            var donePanel = document.getElementById('completionPanel');
            if (finished) {
                this._showCompletion();
            } else if (donePanel) {
                donePanel.style.display = 'none';
                donePanel.innerHTML = '';
            }

            var shock = this._shockFor(q, ds);
            if (shock && alertPanel && alertText) {
                alertText.innerHTML = '<strong>' + this._t('shock_' + shock.id + '_title') + ':</strong> ' +
                                      this._t('shock_' + shock.id + '_desc');
                alertPanel.style.display = 'block';
                if (ds.shockHistory.indexOf(shock.id) === -1) ds.shockHistory.push(shock.id);
            } else if (alertPanel) {
                alertPanel.style.display = 'none';
            }
        }

        // ---------- validation ----------

        validateDecisions(decisions) {
            var st = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state : { currentPeriod: 1, domainState: this._freshDomainState() };
            this._updateBriefing(st);

            var num = function(id, dflt) {
                var e = document.getElementById(id);
                if (!e) return dflt;
                var v = parseInt(e.value, 10);
                return isNaN(v) ? dflt : v;
            };
            var val = function(id, dflt) { var e = document.getElementById(id); return e ? e.value : dflt; };

            decisions.bedAllocation      = num('bedAllocationInput', 15);
            decisions.edThreshold        = num('edThresholdInput', 85);
            decisions.electiveSlots      = num('electiveSlotsInput', 40);
            decisions.nurseRatio         = num('nurseRatioInput', 5);
            decisions.overtimeBudget     = num('overtimeBudgetInput', 25000);
            decisions.trainingInvestment = num('trainingInvestmentInput', 10000);
            decisions.infectionControl   = num('infectionControlInput', 15000);
            decisions.medicationSafety   = num('medicationSafetyInput', 20000);
            decisions.readmissionProgram = num('readmissionProgramInput', 10000);
            decisions.contractStance     = val('contractStanceInput', 'accept');
            decisions.revenueCycle       = num('revenueCycleInput', 10000);
            decisions.charityCare        = num('charityCareInput', 20000);

            var inits = document.getElementsByName('strategicInitiative');
            for (var i = 0; i < inits.length; i++) {
                if (inits[i].checked) { decisions.strategicInitiative = inits[i].value; break; }
            }

            if (decisions.electiveSlots < 20 || decisions.electiveSlots > 60) {
                window.mySimulation.uiManager.showNotification(this._t('elective_slots_warning'), 'warning');
                return false;
            }
            if (decisions.bedAllocation < 10 || decisions.bedAllocation > 25) {
                window.mySimulation.uiManager.showNotification(this._t('bed_allocation_warning'), 'warning');
                return false;
            }
            return true;
        }

        // ---------- results ----------

        calculateResults(state) {
            var d  = state.decisions;
            var ds = state.domainState;
            var q  = state.currentPeriod;

            if (!ds.shockHistory) ds.shockHistory = [];
            var shock = this._shockFor(q, ds);
            var imp   = shock ? shock.impact : {};

            var init    = d.strategicInitiative;
            var effects = this.INITIATIVE_EFFECTS[init] || {};
            var strategicCost = this.STRATEGIC_COSTS[init] || 0;

            ds.cash -= strategicCost;
            if (ds.strategicInvestments.indexOf(init) === -1) ds.strategicInvestments.push(init);

            var leanEffectiveness = 0;
            if (init === 'lean') {
                ds.leanEngagement = (ds.leanEngagement || 0) + (d.trainingInvestment / 10000) * 0.1;
                leanEffectiveness = Math.min(ds.leanEngagement, 1.0);
            }

            // ---- Capacity: ICU allocation now actually does something -----------------------
            // BUGFIX v2.1.0: bedAllocation -- the headline slider on Panel A -- appeared in NO formula
            // in v2.0.0 — the full 10-25% range produced a byte-identical score. It was a
            // decorative control. It now trades ED boarding against ward crowding:
            //   under-allocating ICU  -> critical patients board in the ED -> ED wait rises
            //   over-allocating ICU   -> fewer ward beds -> ward crowding -> quality degrades
            ds.icuBeds = Math.round(ds.totalBeds * (d.bedAllocation / 100));
            var icuGap   = Math.max(0, this.TARGET_ICU_PCT - d.bedAllocation);   // ED boarding
            var icuExcess= Math.max(0, d.bedAllocation - this.TARGET_ICU_PCT);   // ward squeeze

            // ---- Occupancy ------------------------------------------------------------------
            var targetOccupancy = 0.75 + (d.electiveSlots / 200);
            if (imp.edVolume)          targetOccupancy *= imp.edVolume;
            if (imp.capacityReduction) targetOccupancy /= (1 - imp.capacityReduction);
            // Ward beds squeezed by an oversized ICU raise effective crowding.
            targetOccupancy *= (1 + icuExcess * 0.006);
            ds.occupancy = Math.min(0.98, targetOccupancy);

            // ---- Workforce ------------------------------------------------------------------
            var workloadStress = (ds.occupancy * 100) / d.nurseRatio;
            if (imp.nurseAvailability) workloadStress /= imp.nurseAvailability;
            // BUGFIX v2.1.0: overtimeBudget was a pure cost with no effect anywhere. Overtime is
            // how a hospital covers a staffing gap — it now relieves workload stress.
            workloadStress -= (d.overtimeBudget / 100000) * 3;

            var turnoverDelta = (workloadStress - 15) * 0.008 - (d.trainingInvestment / 50000) * 0.02;
            ds.currentNurseTurnover = Math.max(0.10, Math.min(0.45, ds.baseNurseTurnover + turnoverDelta));

            // ---- Quality --------------------------------------------------------------------
            var qualityDegradation = 0;
            if (ds.occupancy > 0.87) {
                qualityDegradation = Math.pow((ds.occupancy - 0.87) / 0.13, 2) * 0.3;
            }

            var handHygiene = 0.75 + (d.infectionControl / 100000) - (workloadStress > 20 ? 0.1 : 0);
            var haiRate = ds.baseHaiRate * (1 - (handHygiene - 0.75)) * (1 + qualityDegradation);
            // ehr_failure: medication errors spike -- declared in v2.0.0, never implemented.
            if (imp.errorRate) {
                var shield = effects.errorShockShield || 0;   // an EHR upgrade blunts this
                haiRate *= 1 + (imp.errorRate - 1) * 0.20 * (1 - shield);
            }
            ds.currentHaiRate = Math.max(0.005, haiRate);

            var medSafetySpend = d.medicationSafety * (1 + (effects.medSafetyBoost || 0));
            var dischargeQuality = (d.readmissionProgram / 50000) + leanEffectiveness * 0.2;
            ds.currentReadmissionRate = Math.max(0.08,
                ds.baseReadmissionRate * (1 - dischargeQuality) * (1 + qualityDegradation * 0.5));

            // ---- ED wait --------------------------------------------------------------------
            var edCapacity = 1 + ((d.edThreshold - 85) / 100);
            var edWait = ds.baseEdWait / edCapacity;
            if (imp.edVolume) edWait *= imp.edVolume;
            edWait *= (1 + icuGap * 0.03);                       // ICU boarding backs up the ED
            if (imp.physicianCapacity) edWait /= imp.physicianCapacity;   // exodus: never implemented
            ds.currentEdWait = Math.round(Math.max(15, edWait));

            // ---- Patient experience ---------------------------------------------------------
            var serviceQuality = (d.nurseRatio <= 4 ? 0.15 : 0)
                               + (medSafetySpend / 80000)
                               - (ds.currentNurseTurnover * 0.3);
            var nps = ds.baseNps + serviceQuality * 20 - qualityDegradation * 30;
            if (imp.reputationHit) nps -= imp.reputationHit;     // inspection: never implemented
            ds.currentNps = Math.round(Math.min(80, Math.max(10, nps)));

            // ---- Revenue --------------------------------------------------------------------
            // BUGFIX v2.1.0: discharges was a hardcoded constant (8500 / 6), so revenue
            // was IDENTICAL whether you ran 20 or 60 elective slots a week. Elective surgery —
            // the profit centre of a hospital -- generated exactly zero revenue, which made the whole
            // capacity-quality paradox a trap with one dominant answer (always minimise
            // slots). Volume now drives revenue, so crowding is a genuine trade-off.
            var electiveCases  = d.electiveSlots * this.WEEKS_PER_QUARTER;
            var emergencyCases = this.EMERGENCY_DISCHARGES;
            if (imp.physicianCapacity) emergencyCases *= imp.physicianCapacity;   // exodus
            var volumeMult = effects.volumeMult || 1.0;          // partnership
            var discharges = (emergencyCases + electiveCases) * volumeMult;

            var contractMult = 1 + (d.contractStance === 'aggressive' ? 0.12
                                  : d.contractStance === 'counter'    ? 0.05 : 0);
            // BUGFIX v2.1.0: revenueCycle was a pure cost appearing in no other formula.
            // Revenue-cycle investment is what a hospital does to actually collect what it bills.
            var collectionRate = 1 + (d.revenueCycle / 40000) * 0.03;

            var revenueMult = effects.revenueMult || 1.0;        // accreditation / service
            if (init === 'service' && d.bedAllocation < (effects.requiresIcuPct || 0)) {
                // A cardiac surgery line without ICU capacity to support it destroys value.
                revenueMult -= (effects.penaltyIfUnsupported || 0);
            }

            var totalRevenue = discharges * this.BASE_RATE * contractMult * collectionRate * revenueMult;
            if (imp.privateVolumeLoss) totalRevenue *= (1 - imp.privateVolumeLoss * 0.3);

            // ---- Costs ----------------------------------------------------------------------
            var laborRatio = this.LABOR_BASE
                           + (d.nurseRatio <= 4 ? -0.03 : d.nurseRatio >= 7 ? 0.05 : 0)
                           + (ds.currentNurseTurnover * 0.2);
            var laborCost  = totalRevenue * laborRatio;
            var supplyCost = totalRevenue * this.SUPPLY_RATIO;
            var adminCost  = totalRevenue * (this.ADMIN_RATIO + (effects.adminRatioDelta || 0));
            var fixedCost  = this.FIXED_COST;                    // genuinely fixed -> operating leverage

            var qualityInvestment = d.infectionControl + d.medicationSafety + d.readmissionProgram + d.revenueCycle;
            var overtimeCost = d.overtimeBudget;
            var charityCost  = d.charityCare;
            var agencyCost   = ds.currentNurseTurnover > 0.25 ? totalRevenue * 0.08 : 0;
            var complianceCost = imp.complianceCost || 0;        // inspection: never implemented

            var totalCosts = laborCost + supplyCost + fixedCost + adminCost + qualityInvestment +
                             overtimeCost + charityCost + agencyCost + strategicCost + complianceCost;

            if (imp.costPremium) totalCosts *= (1 + (imp.costPremium - 1) * 0.3);
            if (imp.cashPenalty) ds.cash -= imp.cashPenalty;

            ds.totalRevenue = totalRevenue;
            ds.totalCosts   = totalCosts;
            var margin = (totalRevenue - totalCosts) / totalRevenue;
            ds.operatingMargin = margin;
            ds.cash += (totalRevenue - totalCosts);

            // audit: receivables freeze -- declared in v2.0.0, never implemented. Cash is held
            // back for the delay window; it is a timing effect, not a permanent loss.
            var heldCash = imp.receivablesDelay ? totalRevenue * (imp.receivablesDelay / 90) : 0;
            ds.daysCashOnHand = Math.round(Math.max(0, (ds.cash - heldCash)) / (totalCosts / 90));

            // ---- Scores (each clamped to the 0-1000 axis the charts actually draw) -----------
            var clamp = function(v) { return Math.round(Math.min(1000, Math.max(0, v))); };

            ds.qualityScore = clamp(
                (1 - ds.currentHaiRate / 0.05) * 300 +
                (1 - ds.currentReadmissionRate / 0.20) * 300 +
                (ds.currentNps / 80) * 400 +
                (effects.qualityBonus || 0)
            );

            ds.efficiencyScore = clamp(
                (1 - Math.min(1, ds.currentEdWait / 120)) * 400 +
                (ds.occupancy > 0.85 ? 200 : ds.occupancy * 300) +
                (leanEffectiveness * 300)
            );

            ds.financialScore = clamp(
                Math.min(400, Math.max(0, margin * 2000)) +
                Math.min(300, ds.daysCashOnHand * 5) +
                (d.contractStance === 'accept' ? 150 : 200)
            );

            ds.workforceScore = clamp(
                (1 - ds.currentNurseTurnover) * 500 +
                (d.trainingInvestment / 50000) * 300 +
                (d.nurseRatio <= 5 ? 200 : 100)
            );

            ds.communityScore = clamp(
                (d.charityCare / 100000) * 400 +
                (effects.communityBonus || 200) +
                (ds.currentNps / 80) * 200
            );

            var quarterScore = Math.round(
                ds.qualityScore    * 0.30 +
                ds.efficiencyScore * 0.25 +
                ds.financialScore  * 0.25 +
                ds.workforceScore  * 0.10 +
                ds.communityScore  * 0.10
            );

            ds.cumulativeScore += quarterScore;

            ds.qualityHistory.push(ds.qualityScore);
            ds.financialHistory.push(ds.financialScore);
            ds.efficiencyHistory.push(ds.efficiencyScore);
            ds.workforceHistory.push(ds.workforceScore);
            ds.communityHistory.push(ds.communityScore);
            ds.scoreHistory.push(quarterScore);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: q + 1, domainState: ds });
            }, 500);

            return {
                period: q,
                quarterScore: quarterScore,
                cumulativeScore: ds.cumulativeScore,
                qualityScore: ds.qualityScore,
                efficiencyScore: ds.efficiencyScore,
                financialScore: ds.financialScore,
                workforceScore: ds.workforceScore,
                communityScore: ds.communityScore,
                cash: ds.cash,
                operatingMargin: ds.operatingMargin,
                daysCashOnHand: ds.daysCashOnHand,
                occupancy: ds.occupancy,
                nurseTurnover: ds.currentNurseTurnover,
                haiRate: ds.currentHaiRate,
                readmissionRate: ds.currentReadmissionRate,
                edWait: ds.currentEdWait,
                nps: ds.currentNps,
                discharges: Math.round(discharges),
                totalRevenue: Math.round(totalRevenue),
                strategicInvestment: init,
                shockEvent: shock ? shock.id : null
            };
        }

