        getPerformanceSummary(history) {
            if (!history || !history.length) return {};

            var final = history[history.length - 1].results || {};
            var avg = function(k) {
                return history.reduce(function(s, h) { return s + ((h.results && h.results[k]) || 0); }, 0) / history.length;
            };
            var avgQuality   = avg('qualityScore');
            var avgFinancial = avg('financialScore');
            var avgEfficiency= avg('efficiencyScore');

            var totalScore    = final.cumulativeScore || 0;
            var finalMargin   = final.operatingMargin || 0;
            var finalTurnover = final.nurseTurnover || 0;
            var finalHai      = final.haiRate || 0;

            // v2.1.0 — bands recalibrated. In v2.0.0 "Excellent" required > 4800 cumulative,
            // which a 512-configuration optimisation could not reach (best: 4136). The top grade
            // was unattainable by construction. Bands are now set against the score range the
            // repaired model can actually produce.
            var band, insights = [];
            // Thresholds set against the range the repaired model MEASURABLY produces
            // (2383 for a careless run -> 4195 for a near-optimal one), not guessed:
            //   > 4050  Excellent  — only disciplined, near-optimal play
            //   > 3400  Competent
            //   > 2700  At Risk
            if (totalScore > 4050)      { band = this._t('band_excellent'); insights.push(this._t('insight_excellent')); }
            else if (totalScore > 3400) { band = this._t('band_competent'); insights.push(this._t('insight_competent')); }
            else if (totalScore > 2700) { band = this._t('band_at_risk');   insights.push(this._t('insight_at_risk')); }
            else                        { band = this._t('band_crisis');    insights.push(this._t('insight_crisis')); }

            if (finalMargin < 0)      insights.push(this._t('insight_neg_margin'));
            if (finalTurnover > 0.30) insights.push(this._t('insight_turnover'));
            if (finalHai > 0.03)      insights.push(this._t('insight_hai'));
            if (avgQuality > 800 && avgFinancial < 500) insights.push(this._t('insight_quality_not_finance'));
            if (avgFinancial > 800 && avgQuality < 500) insights.push(this._t('insight_finance_not_quality'));

            // 0-100 roll-up for the reporting layer. cumulativeScore is unbounded; the v2.1.0
            // recalibration measured the achievable range as ~2383 (careless) to ~4195 (near
            // optimal), so it is normalised against a 4200 ceiling. totalScore is unchanged.
            var overall = Math.max(0, Math.min(100, Math.round((totalScore / 4200) * 100)));

            var summary = {
                totalScore: totalScore,
                overallScore: overall,
                score: overall,
                band: band,
                performance: band,
                averageQuality:   Math.round(avgQuality),
                averageFinancial: Math.round(avgFinancial),
                averageEfficiency:Math.round(avgEfficiency),
                finalCash:    Math.round(final.cash || 0),
                finalMargin:  ((finalMargin) * 100).toFixed(1) + '%',
                finalTurnover:((finalTurnover) * 100).toFixed(1) + '%',
                finalHai:     finalHai,
                insights: insights
            };

            try {
                if (window.mySimulation && window.mySimulation.state) {
                    window.mySimulation.state.performance = summary;
                }
            } catch (e) { /* non-fatal */ }

            return summary;
        }

        getHint(state, results) {
            var ds = state.domainState;
            var d  = state.decisions;
            var p  = state.currentPeriod;

            // BUGFIX v2.1.0: this read `ds.currentPeriod`, which does not exist on domainState.
            // `undefined < 4` is always false, so the occupancy warning — the hint for the
            // sim's headline "capacity-quality paradox" — could never fire, at any occupancy.
            if (ds.occupancy > 0.87 && p < 4)              return this._t('hint_occupancy_warning');
            if (ds.currentNurseTurnover > 0.30)            return this._t('hint_turnover_crisis');
            if (ds.daysCashOnHand < 30)                    return this._t('hint_cash_crisis');
            if (d.strategicInitiative === 'lean' && ds.leanEngagement < 0.3 && p > 2)
                                                            return this._t('hint_lean_engagement');
            if (p === 4 && d.contractStance === 'accept')  return this._t('hint_value_based_opportunity');
            if (ds.currentHaiRate > ds.baseHaiRate * 1.3)  return this._t('hint_infection_spike');
            return null;
        }

